import json,hashlib,re,statistics,subprocess
R=Path(__file__).resolve().parents[1];D=R/'reports'
def read(name):return json.loads((D/name).read_text(encoding='utf8'))
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def main():
 backend=read('institution_v2q_2q1c_closure_backend.json');assert len(backend)==38,'Full inventory not complete'
