 front=read('institution_v2q1c_frontend_tests.json');pres=read('institution_v2q1c_preservation.json');perf=read('institution_v2q1c_fresh_performance.json')
 regress={'backend':counts,'backend_groups':backend,'backend_complete':successful,'frontend':front,'new_test_failures':counts['failed']+front['counts']['failed'],'historical_interrupted_runner':'institution_v2q_2q1c_final_backend.json retained with FileNotFoundError; not counted as completed suite','limitations':'Green regressions do not imply complete AI correctness; genuine Qwen quality failures remain separately reported.'}
